// Explicit HTTP fault fixtures; no wallet, chain, build or broadcast implementation is substituted.
struct HttpFixture{url:String,hits:std::sync::Arc<std::sync::atomic::AtomicUsize>,headers:std::sync::Arc<std::sync::Mutex<Vec<String>>>,stop:std::sync::Arc<std::sync::atomic::AtomicBool>,thread:Option<std::thread::JoinHandle<()>>}
impl Drop for HttpFixture{fn drop(&mut self){self.stop.store(true,std::sync::atomic::Ordering::SeqCst);if let Some(t)=self.thread.take(){t.join().unwrap();}}}
fn http_fixture(answer:impl Fn(usize)->Vec<u8>+Send+'static)->HttpFixture{use std::{io::{BufRead,Write},sync::{Arc,Mutex,atomic::{AtomicBool,AtomicUsize,Ordering}}};let l=std::net::TcpListener::bind("127.0.0.1:0").unwrap();l.set_nonblocking(true).unwrap();let addr=l.local_addr().unwrap();assert!(addr.port()>4142);let hits=Arc::new(AtomicUsize::new(0));let headers=Arc::new(Mutex::new(vec![]));let stop=Arc::new(AtomicBool::new(false));let(h,all,done)=(hits.clone(),headers.clone(),stop.clone());let thread=std::thread::spawn(move||while !done.load(Ordering::SeqCst){match l.accept(){Ok((mut stream,_))=>{stream.set_nonblocking(false).unwrap();stream.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();let mut reader=std::io::BufReader::new(stream.try_clone().unwrap());let mut header=String::new();loop{let mut line=String::new();if reader.read_line(&mut line).unwrap_or(0)==0{break;}header.push_str(&line);if line=="\r\n"{break;}}let n=h.fetch_add(1,Ordering::SeqCst);all.lock().unwrap().push(header);let _=stream.write_all(&answer(n));},Err(_)=>std::thread::sleep(std::time::Duration::from_millis(2))}});HttpFixture{url:format!("http://{addr}/api/quote"),hits,headers,stop,thread:Some(thread)}}
fn raw_http(status:&str,body:&str)->Vec<u8>{format!("HTTP/1.1 {status}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).into_bytes()}
fn required_body()->serde_json::Value{serde_json::json!({"x402Version":1,"error":"X-PAYMENT header is required","accepts":[{"scheme":"zcash-shielded","network":"zcash-testnet","maxAmountRequired":"100000","resource":"http://localhost/api/quote","description":"Explicit synthetic HTTP test fixture","mimeType":"application/json","payTo":"utest1sampleaddressforschemaonly000000","asset":"ZEC","maxTimeoutSeconds":900,"extra":{"memoNonce":"x402z-fixture","expiresAt":4000000000u64}}]})}
#[test]
fn audit_cli_http_failures_before_wallet(){
    let target=http_fixture(|_|raw_http("200 OK","target must not be reached"));
    for(id,args)in [(279,vec!["pay"]),(280,vec!["tab-buy","1","--external"])]{let dir=temp(&format!("http-{id}"));let target_url=target.url.clone();let server=http_fixture(move |_|format!("HTTP/1.1 302 Found\r\nLocation: {target_url}\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").into_bytes());check(cli(&dir,&args,&[("X402Z_TARGET_URL",Some(&server.url))]),1,&["the agent does not follow redirects for paid requests","Nothing was paid."]);assert_eq!(target.hits.load(std::sync::atomic::Ordering::SeqCst),0);let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert!(l.data.audit.is_empty());mark(id);drop(server);std::fs::remove_dir_all(dir).unwrap();}
    for id in [281,282,284,285,286,287,288,289]{let dir=temp(&format!("http-{id}"));let server=http_fixture(move |_|{match id{281=>b"HTTP/1.1 200 OK\r\nContent-Length: 1048577\r\nConnection: close\r\n\r\n".to_vec(),282=>{let mut bytes=b"HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n".to_vec();for _ in 0..5{bytes.extend_from_slice(b"40000\r\n");bytes.extend(vec![b'x';262144]);bytes.extend_from_slice(b"\r\n");}bytes.extend_from_slice(b"0\r\n\r\n");bytes},284=>raw_http("500 Internal Server Error","fixture outage"),285=>raw_http("402 Payment Required","{"),_=>{let mut b=required_body();match id{286=>b["accepts"][0]["scheme"]="exact".into(),287=>b["accepts"][0]["extra"]["expiresAt"]=1.into(),288=>b["accepts"][0]["extra"]["memoNonce"]="bad nonce".into(),_=>{}}raw_http("402 Payment Required",&b.to_string())}}});let o=cli(&dir,&["pay"],&[("X402Z_TARGET_URL",Some(&server.url))]);if id==282&&!String::from_utf8_lossy(&o.stderr).contains("more than 1048576"){println!("streamed fixture stdout length {} diagnostic: {}",o.stdout.len(),String::from_utf8_lossy(&o.stderr));}let parts=match id{281=>vec!["over the agent's limit of 1048576 bytes (X402Z_AGENT_MAX_BODY_BYTES); not read"],282=>vec!["more than 1048576","not read"],284=>vec!["expected 402"],285=>vec!["402 body is not an x402 PaymentRequiredResponse"],286=>vec!["402 offers no zcash-shielded / zcash-testnet payment option"],287=>vec!["402 challenge rejected: Expired"],288=>vec!["402 challenge rejected:"],_=>vec!["X402Z_AGENT_SEED not configured: no funded testnet wallet to pay from"]};check(o,if id==289{4}else{1},&parts);let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert!(l.data.audit.iter().all(|e|e.txid.is_none()));if id==289{assert_eq!(l.data.audit.len(),1);assert!(l.data.audit[0].reason.as_deref().unwrap().starts_with("allowed, but not paid:"));}else{assert!(l.data.audit.is_empty());}assert!(!dir.join("wallet-never-opened").exists());mark(id);drop(server);std::fs::remove_dir_all(dir).unwrap();}
}
fn seeded_pending(dir:&std::path::Path,url:&str)->String{let txid="ab".repeat(32);let mut l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();l.append(AuditEntry{ts:timestamp(),agent:"agent-1".into(),host:"127.0.0.1".into(),amount_zat:100000,decision:"allowed".into(),reason:Some("Explicit synthetic post-broadcast test fixture".into()),memo_nonce:Some("x402z-fixture".into()),txid:Some(txid.clone()),url:Some(url.into()),settled:None});l.save().unwrap();txid}
#[test]
fn audit_cli_resumed_payment_refusal_and_unread_body(){
    for id in [292,293,294,295]{let dir=temp(&format!("resumed-{id}"));let s=http_fixture(move |_|{if id==295{return b"HTTP/1.1 200 OK\r\nContent-Length: 1000\r\nConnection: close\r\n\r\n".to_vec();}let why=if id==292{"invalid_payment"}else{"nonce_already_used"};let settlement=x402z_protocol::SettlementResponse::failed(why);let h=x402z_protocol::encode_header(&settlement);let b=required_body().to_string();format!("HTTP/1.1 402 Payment Required\r\nX-PAYMENT-RESPONSE: {h}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{b}",b.len()).into_bytes()});let txid=seeded_pending(&dir,&s.url);if id==294{let mut l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();l.mark_settled(&txid,true);l.save().unwrap();let cfg= x402z_agent::pay::AgentConfig{ledger_path:Some(dir.join("ledger.json")),wallet_dir:dir.join("unused"),agent:"agent-1".into(),policy:Policy{daily_cap_zat:500000,allowed_hosts:vec!["127.0.0.1".into()],approval_threshold_zat:None},seed:None,ledger_key:Some(LedgerKey::from_bytes([25;32])),birthday:None,lwd_url:String::new(),confirm_timeout_secs:1,poll_secs:0};let runtime=tokio::runtime::Runtime::new().unwrap();let e=runtime.block_on(x402z_agent::pay::redeem_payment(&cfg,&s.url,&txid,"x402z-fixture")).unwrap_err();assert_eq!(e.exit_code(),6);assert!(e.message().contains("Do NOT pay again"));}else{let parts=if id==292{vec!["server refused payment tx"]}else if id==295{vec!["is settled (do not pay again), but its content was not read"]}else{vec!["Do NOT pay again"]};check(cli(&dir,&["pay"],&[("X402Z_TARGET_URL",Some(&s.url))]),if id==292{5}else if id==295{1}else{6},&parts);}
        let l=LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap();assert_eq!(l.data.audit.len(),1);assert_eq!(l.guard("agent-1",&Policy{daily_cap_zat:500000,allowed_hosts:vec!["127.0.0.1".into()],approval_threshold_zat:None},timestamp()).spent_today("agent-1",timestamp()),100000);if id!=292{assert_eq!(l.data.audit[0].settled,Some(true));}assert!(s.headers.lock().unwrap().iter().all(|h|h.to_ascii_lowercase().contains("x-payment:")));mark(id);drop(s);std::fs::remove_dir_all(dir).unwrap();}
}
#[test]
fn audit_broadcast_outcome_accounting_fixture(){use x402z_agent::{pay,wallet};for unknown in [true,false]{let dir=temp(if unknown{"broadcast-unknown"}else{"broadcast-rejected"});let cfg=pay::AgentConfig{ledger_path:Some(dir.join("ledger.json")),wallet_dir:dir.join("unused"),agent:"agent-1".into(),policy:Policy{daily_cap_zat:500000,allowed_hosts:vec!["127.0.0.1".into()],approval_threshold_zat:None},seed:None,ledger_key:Some(LedgerKey::from_bytes([25;32])),birthday:None,lwd_url:String::new(),confirm_timeout_secs:1,poll_secs:0};let mut gate=pay::spendguard_gate(&cfg,"127.0.0.1",100000,"x402z-fixture",&|_,_,_|false).unwrap();let url="http://127.0.0.1:45999/api/quote";gate.audit.url=Some(url.into());let txid="ab".repeat(32);gate.record_broadcasting(&txid).unwrap();let outcome=if unknown{wallet::Broadcast::Unknown("explicit timeout outcome fixture".into())}else{wallet::Broadcast::Rejected("explicit rejection outcome fixture".into())};let e=pay::record_broadcast(gate,&txid,outcome,Some(false)).unwrap_err();assert_eq!(e.exit_code(),1);let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.data.audit.len(),1);if unknown{assert!(e.message().contains("unknown outcome"));assert!(e.message().contains("counts against today's cap"));assert_eq!(l.data.audit[0].txid.as_deref(),Some(txid.as_str()));assert_eq!(l.guard("agent-1",&cfg.policy,timestamp()).spent_today("agent-1",timestamp()),100000);assert_eq!(l.unresolved_payment("agent-1",url,timestamp()).unwrap().txid.as_deref(),Some(txid.as_str()));mark(302);}else{assert!(e.message().contains("explicit rejection outcome fixture"));assert!(e.message().contains("Nothing was paid."));assert!(l.data.audit[0].txid.is_none());assert!(l.data.audit[0].reason.as_deref().unwrap().starts_with("allowed, but not paid:"));assert_eq!(l.guard("agent-1",&cfg.policy,timestamp()).spent_today("agent-1",timestamp()),0);mark(304);}std::fs::remove_dir_all(dir).unwrap();}}
fn audit_cfg(dir:&std::path::Path)->x402z_agent::pay::AgentConfig{x402z_agent::pay::AgentConfig{ledger_path:Some(dir.join("ledger.json")),wallet_dir:dir.join("unused-wallet"),agent:"agent-1".into(),policy:Policy{daily_cap_zat:500000,allowed_hosts:vec!["127.0.0.1".into()],approval_threshold_zat:None},seed:None,ledger_key:Some(LedgerKey::from_bytes([25;32])),birthday:None,lwd_url:"http://127.0.0.1:45999".into(),confirm_timeout_secs:1,poll_secs:15}}
fn pending_reply()->Vec<u8>{let b=required_body().to_string();let h=x402z_protocol::encode_header(&x402z_protocol::SettlementResponse::failed("settlement_pending"));format!("HTTP/1.1 402 Payment Required\r\nX-PAYMENT-RESPONSE: {h}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{b}",b.len()).into_bytes()}
#[test]
fn audit_default_and_explicit_pay_return_paid_json_without_broadcast(){let source=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/src/main.rs"));assert!(source.contains("None | Some(\"pay\") => cmd_pay().await"));for args in [vec![],vec!["pay"]]{let dir=temp(if args.is_empty(){"default-pay"}else{"explicit-pay"});let server=http_fixture(|_|{let body="{\"paid\":\"explicit fixture content\"}";let h=x402z_protocol::encode_header(&x402z_protocol::SettlementResponse::ok(&"ab".repeat(32)));format!("HTTP/1.1 200 OK\r\nX-PAYMENT-RESPONSE: {h}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).into_bytes()});seeded_pending(&dir,&server.url);let out=cli(&dir,&args,&[("X402Z_TARGET_URL",Some(&server.url))]);assert_eq!(out.status.code(),Some(0));assert_eq!(String::from_utf8(out.stdout).unwrap(),"{\"paid\":\"explicit fixture content\"}\n");assert!(String::from_utf8(out.stderr).unwrap().contains(&format!("X-PAYMENT-RESPONSE: success=true transaction={}","ab".repeat(32))));assert_eq!(LedgerFile::load(&dir.join("ledger.json"),&LedgerKey::from_bytes([25;32])).unwrap().data.audit.len(),1);assert!(server.headers.lock().unwrap().iter().all(|h|h.to_ascii_lowercase().contains("x-payment:")));drop(server);std::fs::remove_dir_all(dir).unwrap();}mark(260);}
#[tokio::test]
async fn audit_preparation_network_failure_records_no_payment(){use x402z_agent::pay;let dir=temp("preparation");let mut cfg=audit_cfg(&dir);cfg.seed=Some(secrecy::SecretVec::new(vec![9;64]));let gate=pay::spendguard_gate(&cfg,"127.0.0.1",100000,"x402z-fixture",&|_,_,_|false).unwrap();let e=pay::pay_from_agent_wallet(&cfg,gate,"utest1sampleaddressforschemaonly000000",100000,"x402z-fixture").await.unwrap_err();assert_eq!(e.exit_code(),1);let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.data.audit.len(),1);assert!(l.data.audit[0].reason.as_deref().unwrap().starts_with("allowed, but not paid:"));assert!(l.data.audit[0].txid.is_none());assert_eq!(l.guard("agent-1",&cfg.policy,timestamp()).spent_today("agent-1",timestamp()),0);assert!(!cfg.wallet_dir.exists());mark(291);std::fs::remove_dir_all(dir).unwrap();}
#[tokio::test]
async fn audit_resume_and_short_confirmation_timeout(){use x402z_agent::pay;let dir=temp("resume-pending");let server=http_fixture(|_|pending_reply());let txid=seeded_pending(&dir,&server.url);let cfg=audit_cfg(&dir);let p=match pay::paid_fetch_nowait(&cfg,&server.url,&|_,_,_|false).await.unwrap(){pay::PaidFetch::Pending(p)=>p,_=>panic!("expected pending")};assert_eq!(p.txid,txid);assert_eq!(p.memo_nonce,"x402z-fixture");assert!(p.resumed);assert!(server.headers.lock().unwrap().iter().all(|h|h.to_ascii_lowercase().contains("x-payment:")));let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.data.audit.len(),1);assert_eq!(l.data.audit[0].txid.as_deref(),Some(txid.as_str()));mark(298);
    assert!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/src/pay.rs")).contains("parse_u64(\"X402Z_AGENT_CONFIRM_TIMEOUT_SECS\")?.unwrap_or(900)"));check(cli(&dir,&["pay"],&[("X402Z_TARGET_URL",Some(&server.url)),("X402Z_AGENT_CONFIRM_TIMEOUT_SECS",Some("0"))]),1,&["not settled before timeout","does not pay twice"]);let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.unresolved_payment("agent-1",&server.url,timestamp()).unwrap().txid.as_deref(),Some(txid.as_str()));mark(297);drop(server);std::fs::remove_dir_all(dir).unwrap();}
#[tokio::test]
async fn audit_fifteen_second_retry_cycle_keeps_one_payment(){use x402z_agent::pay;let dir=temp("retry-cycle");let times=std::sync::Arc::new(std::sync::Mutex::new(vec![]));let ts=times.clone();let server=http_fixture(move|n|{ts.lock().unwrap().push(std::time::Instant::now());match n{0=>pending_reply(),1=>raw_http("429 Too Many Requests","{}"),2=>raw_http("502 Bad Gateway","{}"),3=>raw_http("503 Service Unavailable","{}"),4=>vec![],_=>{let h=x402z_protocol::encode_header(&x402z_protocol::SettlementResponse::ok(&"ab".repeat(32)));format!("HTTP/1.1 200 OK\r\nX-PAYMENT-RESPONSE: {h}\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{{}}").into_bytes()}}});let txid=seeded_pending(&dir,&server.url);let mut cfg=audit_cfg(&dir);cfg.confirm_timeout_secs=100;let f=pay::paid_fetch(&cfg,&server.url,&|_,_,_|false).await.unwrap();assert_eq!(f.status,200);let times=times.lock().unwrap();assert_eq!(times.len(),6);for pair in times.windows(2){assert!(pair[1].duration_since(pair[0])>=std::time::Duration::from_secs(14));}let headers=server.headers.lock().unwrap();let payments:Vec<_>=headers.iter().map(|h|h.lines().find(|l|l.to_ascii_lowercase().starts_with("x-payment:")).unwrap()).collect();assert!(payments.iter().all(|p|*p==payments[0]));drop(headers);let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.data.audit.len(),1);assert_eq!(l.data.audit[0].txid.as_deref(),Some(txid.as_str()));assert_eq!(l.guard("agent-1",&cfg.policy,timestamp()).spent_today("agent-1",timestamp()),100000);mark(296);drop(server);std::fs::remove_dir_all(dir).unwrap();}
#[tokio::test]
async fn audit_all_paying_entry_points_preflight_before_requests(){use x402z_agent::{pay,tab};let dir=temp("all-preflight");let server=http_fixture(|_|raw_http("500 Internal Server Error","must not be requested"));let mut cfg=audit_cfg(&dir);cfg.policy.allowed_hosts=vec!["not-this-host.local".into()];assert_eq!(pay::paid_fetch(&cfg,&server.url,&|_,_,_|false).await.unwrap_err().exit_code(),3);assert_eq!(pay::redeem_payment(&cfg,&server.url,&"ab".repeat(32),"x402z-fixture").await.unwrap_err().exit_code(),3);assert_eq!(tab::buy_or_resume(&cfg,&server.url,1,&|_,_,_|false,false).await.unwrap_err().exit_code(),3);assert_eq!(tab::fetch(&cfg,&server.url).await.unwrap_err().exit_code(),3);assert_eq!(server.hits.load(std::sync::atomic::Ordering::SeqCst),0);let l=LedgerFile::load(cfg.ledger_path.as_ref().unwrap(),cfg.key().unwrap()).unwrap();assert_eq!(l.data.audit.len(),3);assert!(l.data.audit.iter().all(|e|e.txid.is_none()&&e.memo_nonce.is_none()));mark(278);drop(server);std::fs::remove_dir_all(dir).unwrap();}
